    correction: [{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 3</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 3</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">5(b + 3) + 3b = 143</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">5b + 15 + 3b = 143</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">8b + 15 = 143</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">8b = 143 - 15</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 128 : 8 = 16</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 3 = 19</span>"}],
